#include <iostream>
#include <vector>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

constexpr int64 MOD = 998244353;

int64 mod(i128 value) {
    value %= MOD;
    if (value < 0) value += MOD;
    return static_cast<int64>(value);
}

int64 mul(int64 a, int64 b) {
    return static_cast<int64>(static_cast<i128>(a) * b % MOD);
}

vector<bool> getPrimes(int n) {
    vector<bool> isPrime(n + 1, true);
    if (n >= 0) isPrime[0] = false;
    if (n >= 1) isPrime[1] = false;

    vector<int> primes;
    for (int i = 2; i <= n; ++i) {
        if (isPrime[i]) primes.push_back(i);
        for (int prime : primes) {
            if (static_cast<int64>(prime) * i > n) break;
            isPrime[prime * i] = false;
            if (i % prime == 0) break;
        }
    }
    return isPrime;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    int64 m;
    cin >> n >> m;

    i128 pre = 1;
    int64 M = mod(m);
    int64 res = 0;
    int64 ans = M;
    int64 ans1 = M;

    vector<bool> isPrime = getPrimes(n + 10);

    for (int i = 2; i <= n; ++i) {
        if (pre <= m && isPrime[i]) pre *= i;

        if (pre > m) {
            ans = 0;
        } else {
            ans = mul(ans, mod(static_cast<i128>(m) / pre));
        }

        ans1 = mul(ans1, M);
        res = mod(static_cast<i128>(res) + ans1 - ans);
    }

    cout << res;
    return 0;
}

